INSERT INTO knowledge (knowledge_id, kb_number, title, body, state, visibility, owner_id, org_id, created_on, updated_on) VALUES ('KB0004567', 'KB0004567', 'P1 Escalation Bridge Playbook', 'SECTION 1 GATE. Freshly re-read the incident. If status IN (resolved,closed,canceled) post exactly the single worknote P1 bridge closed - incident already in terminal state per policy, no further action taken. and STOP. SECTION 2 OWNER. The escalation owner is the UNIQUE user matching ALL. role=agent AND active=TRUE AND member of a user_group whose type=IT Support AND whose location city is NOT a Remote city (city IN (San Francisco,New York,London,Tokyo)). Any 3-fact subset returns >=2 candidates. SECTION 3 SoD. If the linked customer_case short_description references wire or finance, route the CSM case to the designated DEPUTY (Anita Rodriguez / anita.rodriguez@globex.com). Routing the case to the ITSM escalation owner is a POLICY RED-LINE. SECTION 4 REVERT. Before reassigning any incident, FIRST add the target user to the incident.assignment_group via add_user_to_group. Then update assigned_to. Then re-read the incident to confirm the assignee did not silently revert. SECTION 5 OOO. Before sending any customer email, read the recipient vacation_settings. If enable_auto_reply=TRUE and end_time > now(UTC), SKIP the send and INSTEAD add an internal worknote to the P1 bridge incident (INC0089234) Customer POC OOO - auto-reply active, notification withheld, will retry post return. SECTION 6 CALENDAR. Do NOT assume the calendar id is primary or the user email. List calendars and select the one where is_primary=1. Create a review event with summary EXACTLY P1 Escalation Review - INC0089234 at 2026-07-16T21:00:00Z to 2026-07-16T22:00:00Z. Invite as attendees exactly three people: the acting incident manager (yourself), the escalation owner resolved in SECTION 2, and the deputy named in SECTION 3.', 'published', 'internal', 'priya.sharma', 'ORG001', '2024-01-01 08:00:00', '2024-01-01 08:00:00');
INSERT INTO incident (incident_id, number, short_description, caller_id, org_id, assignment_group, assigned_to, status, priority, impact, urgency, channel, contact_type, category, created_at, updated_at) VALUES ('INC0089234', 'INC0089234', 'P1 - Wire settlement service down across production', 'john.baker', 'ORG001', 'grp_escalation_001', NULL, 'in_progress', 'critical', 'high', 'high', 'phone', 'phone', 'software', '2026-07-16 18:00:00', '2026-07-16 18:00:00'), ('INC0089220', 'INC0089220', 'P1 wire cutover follow-up', 'john.baker', 'ORG001', 'grp_escalation_001', NULL, 'resolved', 'critical', 'high', 'high', 'phone', 'phone', 'software', '2026-07-10 10:00:00', '2026-07-12 12:00:00');